/** Original Russian learning route. Exercises are virtual or desk-based.
 * This is a foundation for further study, not professional certification.
 * Unlocks apply AFTER completion; all prepared lab samples are cabinet stocks.
 */
export const CHAPTERS = [
 {id:'chapter-01',title:'Первые наблюдения',subtitle:'Освоиться за столом и отделить увиденное от объяснения'},
 {id:'chapter-02',title:'Язык частиц',subtitle:'Атомы, периодичность, ионы, связи и количество вещества'},
 {id:'chapter-03',title:'Химия в числах',subtitle:'Моль, концентрация, пропорции и проверяемый результат'},
 {id:'chapter-04',title:'Кислоты и основания',subtitle:'Перенос протона, pH, нейтрализация и буферные системы'},
 {id:'chapter-05',title:'Неорганические превращения',subtitle:'Осадки, растворимость и маршруты между классами веществ'},
 {id:'chapter-06',title:'Энергия и фазы',subtitle:'Тепло, энтальпия, энтропия и направление превращений'},
 {id:'chapter-07',title:'Скорость и равновесие',subtitle:'Почему реакция идёт быстро, медленно или не до конца'},
 {id:'chapter-08',title:'Электроны в движении',subtitle:'Окисление, гальванический элемент и электрохимические расчёты'},
 {id:'chapter-09',title:'Устройство органических молекул',subtitle:'Структура, группы, изомерия, механизмы и спектры'},
 {id:'chapter-10',title:'Молекулы жизни и материалы',subtitle:'Углеводы, белки, ферменты, полимеры и связь структуры со свойствами'},
 {id:'chapter-11',title:'Как измеряет химик',subtitle:'Неопределённость, титрование, приборные методы и план опыта'},
 {id:'chapter-12',title:'От опыта к исследованию',subtitle:'Источники, данные, воспроизводимость и самостоятельный проект'}
];

export const LESSONS=[];
const q=(prompt,options,correct,feedback)=>({prompt,options,correct,feedback});
const analysis=(title,prompt,options,correct,feedback)=>({type:'analysis',title,instructions:['Прочитайте условие и выберите вывод, который поддерживают данные.'],prompt,options,correct,feedback});
const calc=(title,prompt,answer,unit,feedback,tolerance=.01)=>({type:'calculation',title,instructions:['Запишите исходные величины и единицы. Выполните расчёт и введите результат.'],prompt,answer,tolerance,unit,feedback});
const lab=(title,setup,goal,instructions,feedback)=>({type:'lab',title,setup,goal,instructions:['Работайте с подготовленными предметами на виртуальном столе.',...instructions],feedback});
function lesson(n,chapter,title,hook,paragraphs,example,remember,notebookPrompt,questions,practice,substances=[],equipment=[]){
 LESSONS.push({id:`lesson-${String(n).padStart(2,'0')}`,chapter:`chapter-${String(chapter).padStart(2,'0')}`,title,minutes:practice.type==='lab'?14:10,hook,paragraphs,example,remember,notebookPrompt,questions,practice,unlock:{substances,equipment}});
}

lesson(1,1,'Сначала наблюдение','Что можно узнать о воде, ещё ничего с ней не делая?',[
 'Химия начинается с описания образца. Агрегатное состояние — его физическая форма: например, твёрдая, жидкая или газообразная. Название, состояние, температура и наблюдаемый цвет — разные характеристики. Прозрачное содержимое может быть водой, раствором соли или смесью нескольких веществ.',
 'Панель сосуда показывает данные учебной модели. Это удобный инструмент наблюдения, но не настоящий универсальный анализатор: в реальной лаборатории состав устанавливают отдельными методами. Сначала запишите наблюдение, затем предложите объяснение.'
],'«Жидкость прозрачна» — наблюдение. «В ней нет растворённых веществ» — гипотеза, которую прозрачность не доказывает.','Внешний вид не определяет состав однозначно.','Запишите три характеристики воды и один вопрос, на который пока нельзя ответить.',[
 q('Прозрачность образца доказывает его чистоту?',['Да, примеси всегда видны','Нет, многие растворы прозрачны'],1,['Растворённые частицы часто не видны глазом.','Верно: прозрачный раствор может содержать несколько веществ.']),
 q('Что является наблюдением?',['Температура на панели равна 22 °C','Все бесцветные жидкости одинаковы'],0,['Это конкретное показание прибора модели.','Это обобщение, не подтверждённое наблюдением.'])
],lab('Рассмотрите воду',{kind:'inspect',receiver:{kind:'beaker',substance:'water',volume:30}},{type:'inspect',substance:'water'},['Выберите подготовленный стакан с водой.','Прочитайте состав, объём и температуру в панели предмета.'],'Осмотр — самостоятельный этап опыта: теперь есть исходные данные.'),[],['graduated_cylinder']);

lesson(2,1,'Первое переливание','Как перенести жидкость, сохранив контроль над её количеством?',[
 'При переливании меняется положение вещества, но не обязательно его состав. В игре содержимое движется через горлышко открытого наклонённого сосуда. Капли несут те же компоненты, что и исходная смесь.',
 'Система для учёта вещества может включать оба сосуда, капли и лужу. Если считать только принимающий стакан, потеря на стол покажется исчезновением. Всегда указывайте границы того, что измеряете.'
],'Из 30 мл исходной воды 12 мл попали в стакан, 2 мл — на стол, 16 мл остались в бутылке. Все 30 мл учтены.','Перенос и химическое превращение — разные события.','Нарисуйте границы вашей системы и отметьте все места, где оказалась вода.',[
 q('Вода пролилась на стол. Она исчезла из всей системы?',['Нет, она оказалась в луже','Да, если её нет в стакане'],0,['При включении стола в систему вещество остаётся учтённым.','Стакан — лишь часть выбранной системы.']),
 q('Что необходимо для переливания в этой игре?',['Открытое горлышко и подходящий наклон','Одинаковый цвет сосудов'],0,['Именно геометрия и открытое горлышко определяют поток.','Оформление предметов не является условием переноса.'])
],lab('Перелейте не менее 8 мл',{kind:'pour',receiver:{kind:'beaker'},donor:{substance:'water',volume:30}},{type:'pour',substance:'water',minVolume:8},['ЛКМ возьмите бутылочку и поднесите горлышко над пустым стаканом.','Наклоните колесом, затем верните вертикально и отпустите ПКМ.'],'Жидкость перенесена. Сравните объёмы и проверьте, не осталось ли части воды на столе.'),[],['flask']);

lesson(3,1,'Вещество или смесь?','Почему у морской воды нет единственной формулы?',[
 'Индивидуальное вещество имеет определённый химический состав. Смесь содержит несколько веществ, соотношение которых может меняться. Раствор — однородная смесь, а суспензия включает отдельную твёрдую фазу.',
 'Элемент — вид атомов, а соединение объединяет атомы разных элементов в определённом составе. Символ Na обозначает натрий, формула NaCl — состав хлорида натрия. Запись NaCl(aq) означает соль в водной среде, а не бутылку чистой жидкой соли.'
],'Растворы с 1 и 5 г соли могут выглядеть одинаково, но это смеси разного состава. Формула самой соли остаётся NaCl.','У смеси может быть однородный вид без постоянного состава.','Приведите по одному примеру вещества, раствора и суспензии.',[
 q('Однородный раствор обязательно является индивидуальным веществом?',['Да','Нет'],1,['Однородность описывает распределение компонентов, а не их число.','Верно: раствор может быть однородной смесью.']),
 q('Что означает aq после формулы?',['Водный раствор','Абсолютную чистоту'],0,['Это обозначение водной среды.','Чистота не кодируется обозначением aq.'])
],analysis('Прозрачные образцы','В двух пробах одинаковый объём воды, но разное количество растворённой соли. Что можно заключить?',['Это одно и то же по составу','Обе пробы — растворы, их концентрации различаются'],1,'Количество растворённого вещества на одинаковый объём различается: это разные концентрации.'),['sodium_chloride']);

lesson(4,1,'От признака к гипотезе','Пузырьки уже доказывают образование нового газа?',[
 'Изменение цвета, появление осадка, нагрев или пузырьки помогают заметить процесс. Каждый признак допускает несколько объяснений: пузырьки бывают при кипении, выходе растворённого воздуха и химической реакции.',
 'Хорошая гипотеза связывает конкретные условия с проверяемым результатом. Контрольная проба отличается только изучаемым фактором. В журнале полезно разделить «что сделано», «что увидено» и «что предполагается».'
],'При добавлении жидкости к порошку появились пузырьки. Сравните такой же порошок с водой, прежде чем связывать эффект только с кислотой.','Признак подсказывает гипотезу, но не заменяет проверку.','Сформулируйте гипотезу о газе и назовите подходящую контрольную пробу.',[
 q('Можно ли назвать любой пузырёк продуктом химической реакции?',['Да, газ возникает только в реакции','Нет, возможны физические причины'],1,['Кипение и выделение растворённого воздуха тоже дают пузырьки.','Верно: нужны условия и дополнительные признаки.']),
 q('Зачем нужна контрольная проба?',['Чтобы отделить влияние изучаемого фактора','Чтобы всегда получить более яркий эффект'],0,['Контроль помогает проверить альтернативное объяснение.','Яркость не является целью контрольного сравнения.'])
],analysis('Выберите проверку','Хотим узнать, связано ли газовыделение с уксусной кислотой. Какую пару сравнить?',['Сода с кислотой и такая же сода с водой','Два разных порошка с разными кислотами'],0,'В первой паре меняется один фактор — наличие кислоты; во второй причин несколько.'),['sodium_bicarbonate','acetic_acid']);

lesson(5,1,'Первый газ','У реакции есть начало, расход реагентов и продукты.',[
 'Гидрокарбонат натрия реагирует с уксусной кислотой: образуются ацетат натрия, вода и углекислый газ. В открытой посуде CO₂ покидает раствор, поэтому пузырьки показывают движение одного из продуктов.',
 'В уравнении формулы слева от стрелки обозначают исходные вещества, справа — продукты. После реакции может остаться избыток одного реагента вместе с солью. Даже если пузырьки исчезли, это не гарантирует чистый продукт: название смеси должно соответствовать оставшемуся составу.'
],'NaHCO₃ + CH₃COOH → CH₃COONa + CO₂ + H₂O. Число атомов каждого элемента сохраняется по обе стороны записи.','Окончание пузырьков не доказывает чистоту содержимого.','Запишите признаки реакции, уравнение и компоненты оставшейся смеси.',[
 q('Какой газ даёт эта поддерживаемая реакция?',['CO₂','O₂'],0,['Карбонатная часть даёт углекислый газ.','Кислород относится к другим реакциям, например разложению пероксида.']),
 q('Если кислоты осталось слишком много, после опыта сосуд содержит…',['Только чистый ацетат','Ацетат и избыток кислоты в воде'],1,['Неизрасходованный реагент не исчезает автоматически.','Верно: избыток сохраняется в составе смеси.'])
],lab('Наблюдайте карбонатную реакцию',{kind:'pour',receiver:{kind:'beaker',substance:'acetic_acid',volume:25},donor:{substance:'sodium_bicarbonate',volume:30}},{type:'reaction',id:'bicarbonate_acetic'},['Перелейте часть раствора соды в подготовленный раствор кислоты.','Найдите событие газовыделения и проверьте состав в панели.'],'Реакция зарегистрирована по изменению состава, а не по одной анимации.'),[],['dropper']);

lesson(6,2,'Атомы и изотопы','Почему атомы одного элемента могут иметь разную массу?',[
 'Атом состоит из положительно заряженного ядра и окружающих его отрицательных электронов. В ядре находятся протоны с положительным зарядом и нейтроны без заряда. Число протонов Z определяет элемент; в нейтральном атоме число электронов равно Z.',
 'Число нейтронов у атомов одного элемента может различаться. Такие разновидности называются изотопами: у них одинаковое Z, но разное массовое число A.',
 'Массовое число — число протонов и нейтронов конкретного ядра. Относительная атомная масса в таблице обычно отражает изотопный состав образца и потому не обязана быть целым числом. Эти величины нельзя подменять друг другом.'
],'Для ¹³C: Z = 6, A = 13, значит в ядре 7 нейтронов. Атом остаётся углеродом, как и ¹²C.','Элемент задают протоны; изотоп — конкретный состав ядра.','Объясните разницу между массовым числом и атомной массой в таблице.',[
 q('Что изменится при добавлении нейтрона к ядру углерода?',['Изотоп','Сам элемент'],0,['Число протонов прежнее, изменяется изотоп.','Элемент меняется при изменении числа протонов.']),
 q('Сколько электронов у нейтрального атома с Z = 8?',['8','16'],0,['Нейтральность требует равенства чисел электронов и протонов.','Масса и число электронов не складываются таким образом.'])
],calc('Посчитайте нейтроны','У ядра A = 56 и Z = 26. Сколько нейтронов?',30,'нейтронов','N = A − Z = 56 − 26 = 30.',0),['iron']);

lesson(7,2,'Периодичность без магии','Почему соседство в таблице помогает предсказывать свойства?',[
 'Расположение элементов связано со строением электронных оболочек. Валентные электроны — электроны, участвующие в образовании химических связей. У элементов одной группы часто сходно их число и похожи типы соединений, но это закономерность с условиями, а не список одинаковых веществ.',
 'Размер атома, энергия ионизации и электроотрицательность меняются по таблице закономерно. Для переходных металлов важны несколько доступных степеней окисления: железо(II) и железо(III) дают разные соединения и наблюдения.'
],'FeCl₂ и FeCl₃ содержат один элемент железо, но разные отношения атомов и степени окисления. Нельзя ожидать от них одинакового осадка.',
 'Таблица помогает выдвигать прогноз, который уточняют условиями и строением.','Выберите два элемента одной группы и объясните, какое сходство ожидаете.',[
 q('Элементы одной группы обязаны иметь одинаковую реакционную способность?',['Нет, сходство не означает тождества','Да, различается только название'],0,['Размер, энергия связи и другие факторы различаются.','Периодическая закономерность не делает элементы одинаковыми.']),
 q('Число III в названии хлорид железа(III) указывает…',['Степень окисления железа','Три разных изотопа железа'],0,['Это формальный электронный учёт в соединении.','Изотопный состав таким обозначением не задаётся.'])
],analysis('Сравните записи','Почему FeCl₂ и FeCl₃ нельзя считать одной солью?',['У них различаются состав и состояние окисления железа','Любые соли одного металла одинаковы'],0,'Разное соотношение ионов приводит к различным свойствам и реакциям.'),['copper','zinc']);

lesson(8,2,'Ионы и электронейтральность','Как заряд помогает восстановить формулу соли?',[
 'Ион — атом или группа связанных атомов с общим электрическим зарядом. Катион имеет положительный заряд, а анион — отрицательный. Формула нейтрального ионного соединения должна давать нулевую сумму зарядов. Коэффициент при ионе и его заряд — разные вещи.',
 'Сложный ион, например SO₄²⁻, может содержать несколько элементов и в некоторых реакциях переходить как единая группа. Скобки показывают повторение всей группы: Ca(OH)₂ содержит два O и два H.'
],'Для Ca²⁺ и Cl⁻ нужны два хлорид-иона: (+2) + 2·(−1) = 0, поэтому формула CaCl₂.','Сумма зарядов формульной единицы нейтральной соли равна нулю.','Составьте формулы для Mg²⁺/Cl⁻ и Na⁺/SO₄²⁻ и покажите проверку зарядов.',[
 q('Какова сумма зарядов в CaCl₂?',['0','+1'],0,['Один Ca²⁺ уравновешен двумя Cl⁻.','Один хлорид-ион был бы недостаточен.']),
 q('Сколько атомов кислорода в Ca(OH)₂?',['1','2'],1,['Индекс после скобок относится ко всей группе OH.','Две группы OH содержат два атома кислорода.'])
],calc('Баланс заряда','Сколько ионов Na⁺ необходимо на один SO₄²⁻ в нейтральной соли?',2,'иона','Два положительных единичных заряда компенсируют −2.',0),['calcium_carbonate']);

lesson(9,2,'Связи и свойства','Почему формула не всегда описывает отдельную молекулу?',[
 'Ковалентная связь связана с распределением электронной плотности между атомами; ионное описание подчёркивает притяжение зарядов. Между крайними моделями есть множество промежуточных случаев.',
 'NaCl в кристалле образует ионную решётку, поэтому его формула задаёт отношение ионов, а не маленькую отдельную молекулу соли. У воды есть молекулы; у кварца — пространственная сеть. Тип строения влияет на растворимость и свойства.'
],'Запись SiO₂ говорит об отношении Si:O = 1:2. Она не требует существования отдельных молекул SiO₂ в кристалле кварца.','Формула состава и устройство вещества — не одно и то же.','Сравните молекулярное, ионное и сетчатое строение на трёх примерах.',[
 q('Формула NaCl в кристалле главным образом задаёт…',['Соотношение Na⁺ и Cl⁻','Размер отдельной капли соли'],0,['Это простейшее отношение ионов в решётке.','Формула не является описанием размера образца.']),
 q('Полярная связь означает полный переход электрона в каждом случае?',['Да','Нет, распределение электронной плотности бывает неравномерным без полного переноса'],1,['Это слишком грубое отождествление полярной и ионной моделей.','Полярность описывает неравномерное распределение электронной плотности.'])
],lab('Рассмотрите раствор соли',{kind:'inspect',receiver:{kind:'beaker',substance:'sodium_chloride',volume:20}},{type:'inspect',substance:'sodium_chloride'},['Выберите стакан и найдите воду и NaCl среди компонентов.','Объясните, почему общая формула соли не означает, что раствор состоит из одного вещества.'],'Раствор содержит соль и растворитель; ионное строение объясняется моделью, а не видимостью отдельных частиц.'),['silica']);

lesson(10,2,'Моль как счётная единица','Как перейти от невидимых частиц к измеряемой массе?',[
 'Моль — единица количества вещества. Один моль содержит точно 6,02214076·10²³ указанных частиц: атомов, молекул, ионов или формульных единиц. Название частиц обязательно, иначе число теряет смысл.',
 'Молярная масса M связывает массу m и количество n: n = m/M. Миллимоль в тысячу раз меньше моля. В игре состав хранится в ммоль, поэтому одинаковый объём разных растворов не обязательно содержит одинаковое количество реагента.'
],'18,0 г воды при M ≈ 18,0 г/моль соответствуют примерно 1,00 моль молекул H₂O, но 2,00 моль атомов водорода.','Всегда указывайте, какие частицы считает моль.','Объясните, почему один моль воды содержит два моля атомов водорода.',[
 q('Один ммоль равен…',['0,001 моль','1000 моль'],0,['Приставка милли означает одну тысячную.','Это обратное соотношение.']),
 q('Одинаковая масса разных веществ всегда даёт одинаковое n?',['Да','Нет, нужно знать молярную массу'],1,['Разные частицы имеют разные молярные массы.','В формуле n = m/M значение M зависит от вещества.'])
],calc('Масса в количество','Сколько моль составляет 9,0 г воды, если M = 18,0 г/моль?',.5,'моль','n = 9,0 / 18,0 = 0,50 моль.',.001),[],['thermometer','burner','stand']);

lesson(11,3,'Единицы защищают от ошибок','Почему результат в тысячу раз больше ожидаемого?',[
 'Перед вычислением выберите согласованные единицы. В отношении массы к молярной массе граммы сокращаются, остаются моли. Объём в миллилитрах нельзя без преобразования подставлять в формулу, где концентрация задана в моль на литр.',
 'Размерностная проверка не гарантирует верность всей модели, но ловит многие арифметические ошибки. Полезно заранее оценить порядок результата: маленькая лабораторная проба редко содержит сотни молей растворённой соли.'
],'0,020 л · 0,50 моль/л = 0,010 моль = 10 ммоль. Единицы литра сокращаются.','Сначала единицы и порядок величины, затем точные цифры.','Запишите один расчёт в моль и тот же расчёт в ммоль.',[
 q('Сколько литров в 25 мл?',['0,025 л','25 000 л'],0,['Один литр содержит тысячу миллилитров.','Перевод выполнен в неверном направлении.']),
 q('Какую размерность имеет cV при c в моль/л и V в л?',['моль','моль/л²'],0,['Литры сокращаются при умножении.','Умножение на объём не добавляет литр в знаменатель.'])
],calc('Проверьте единицы','Сколько ммоль содержит 20 мл раствора с c = 0,50 моль/л?',10,'ммоль','0,020 · 0,50 = 0,010 моль = 10 ммоль.',.001),[],['hotplate']);

lesson(12,3,'Концентрация не равна количеству','Что общего у маленькой крепкой пробы и большой разбавленной?',[
 'Молярная концентрация c = n/V описывает количество растворённого вещества на объём раствора. Величина n характеризует весь выбранный образец, а c — его состав на единицу объёма.',
 'При отборе части хорошо перемешанного раствора количество вещества уменьшается вместе с объёмом, но концентрация сохраняется. Это предположение нарушится, если проба неоднородна или содержит оседающие частицы.'
],'10 ммоль соли в 20 мл раствора и 50 ммоль в 100 мл дают одну концентрацию: 0,50 моль/л.','При одинаковой концентрации больший объём содержит больше вещества.','Придумайте два разных образца с одинаковой концентрацией.',[
 q('Из однородного раствора отобрали половину. Концентрация этой части…',['Сохранилась','Обязательно уменьшилась вдвое'],0,['И количество, и объём уменьшились в одинаковой пропорции.','Вы путаете концентрацию с общим количеством вещества.']),
 q('Для c = n/V используют объём…',['Всего раствора','Только добавленной воды в любом случае'],0,['Определение относится к объёму раствора.','Объёмы при смешивании не всегда складываются идеально.'])
],calc('Найдите концентрацию','В 50 мл раствора содержится 5 ммоль вещества. Найдите c в моль/л.',.1,'моль/л','0,005 моль / 0,050 л = 0,10 моль/л.',.001),[],['evaporating_dish']);

lesson(13,3,'Разбавление и сохранение','Можно уменьшить концентрацию, не забирая ни одной частицы соли.',[
 'При добавлении чистого растворителя количество нелетучего растворённого вещества сохраняется, а объём увеличивается. Для такого процесса c₁V₁ = c₂V₂, если реакции и потерь нет.',
 'Эта формула не является универсальным законом любого смешивания. Когда компоненты реагируют, испаряются или выпадают в осадок, сначала нужен баланс вещества с учётом процесса. Для слабой кислоты pH также не изменяется по тому же правилу, что концентрация.'
],'Если 20 мл раствора мысленно довести до 40 мл без потерь, его концентрация уменьшится вдвое. Количество вещества останется прежним.','Разбавление меняет концентрацию, а не само количество растворённого вещества.','Сравните количество кислоты до добавления воды и после него.',[
 q('При добавлении воды без реакции n растворённого вещества…',['Сохраняется','Автоматически удваивается'],0,['Чистая вода не приносит новый реагент этого вида.','Удваивается не количество солюта, а может увеличиться объём.']),
 q('Можно ли применять c₁V₁ = c₂V₂ к реагенту, который расходуется в реакции?',['Без поправок нельзя','Всегда можно'],0,['Нужно сначала учесть химический расход.','Равенство требует сохранения количества рассматриваемого компонента.'])
],lab('Разбавьте раствор кислоты',{kind:'pour',receiver:{kind:'beaker',substance:'acetic_acid',volume:20},donor:{substance:'water',volume:20}},{type:'pour',substance:'water',minVolume:15},['Добавьте воду в подготовленный раствор.','Сравните увеличение объёма с количеством CH₃COOH в панели.'],'Перенесён растворитель. Изменение объёма само по себе не является образованием нового соединения.'));

lesson(14,3,'Ограничивающий реагент','Реакция заканчивается, когда заканчивается нужный участник.',[
 'Коэффициенты уравнения задают отношения количеств участников, а не масс. Для NaHCO₃ и уксусной кислоты отношение 1:1: каждый миллимоль одного реагента требует миллимоль другого.',
 'Ограничивающий реагент задаёт максимально возможное количество продукта. Избыток второго участника остаётся в сосуде. Сравнивать нужно n, делённое на соответствующий коэффициент, особенно когда коэффициенты не равны единице.'
],'Если есть 5 ммоль кислоты и 10 ммоль гидрокарбоната, максимум получится 5 ммоль ацетата; 5 ммоль гидрокарбоната останется.','Сравнивайте количество с коэффициентом реакции, а не только объём бутылки.','Назовите ограничивающий реагент и предскажите состав остатка.',[
 q('При отношении 1:1 и запасах 3 и 7 ммоль максимум продукта равен…',['3 ммоль','7 ммоль'],0,['Первый реагент ограничивает число возможных превращений.','Четырём миллимолям второго реагента не хватает партнёра.']),
 q('Если коэффициенты 1:2, равные количества реагентов обязательно оптимальны?',['Нет','Да'],0,['Второго реагента требуется вдвое больше по количеству.','Равенство запасов не совпадает с отношением 1:2.'])
],lab('Проследите избыток реагента',{kind:'pour',receiver:{kind:'beaker',substance:'acetic_acid',volume:10},donor:{substance:'sodium_bicarbonate',volume:25}},{type:'reaction',id:'bicarbonate_acetic'},['Добавляйте раствор гидрокарбоната и наблюдайте событие реакции.','После опыта посмотрите, какие исходные вещества ещё присутствуют.'],'Событие реакции подтверждено. Для вывода об избытке используйте полный состав и реально перелитое количество.'));

lesson(15,3,'Теоретический и фактический выход','Почему расчётное количество продукта не равно полученному образцу?',[
 'Теоретический выход следует из уравнения и ограничивающего реагента. Фактический выход — измеренное количество выделенного продукта. Их отношение, умноженное на 100 %, даёт процентный выход.',
 'Меньший выход может быть связан с неполным превращением, потерями при переносе или побочными процессами. Значение выше 100 % часто указывает на примеси, влажный образец или ошибку измерения, а не на создание вещества сверх баланса.'
],'Теория предсказывает 20 ммоль продукта, а после выделения получено 16 ммоль: выход 80 %.','Выход требует одного и того же продукта и согласованных единиц.','Перечислите две причины заниженного и одну причину завышенного выхода.',[
 q('Измеренный выход 115 % чаще требует…',['Проверки чистоты и измерений','Признания нарушения сохранения атомов'],0,['Примеси и вода могут завысить измеренную массу.','Сначала проверяют метод и состав образца.']),
 q('В формуле выхода знаменатель — это…',['Теоретически возможное количество','Любое начальное количество реагента'],0,['Сравниваются фактический и теоретический продукт.','Начальный реагент нужно сначала пересчитать по стехиометрии.'])
],calc('Оцените выход','Теоретически возможно 20 ммоль, фактически выделено 16 ммоль продукта. Каков выход?',80,'%','η = 16 / 20 · 100 % = 80 %. ',.01),['hcl','naoh'],['crucible']);

lesson(16,4,'Кислота и основание встречаются','В центре кислотно-основного описания — перенос протона.',[
 'В модели Брёнстеда кислота отдаёт протон, а основание принимает его. Для сильной кислоты и сильной щёлочи в воде ключевое сокращённое превращение: H₃O⁺ + OH⁻ → 2H₂O.',
 'Нейтрализация HCl раствором NaOH даёт воду и раствор соли. Реакция выделяет тепло, но конечная температура зависит от количества вещества, воды, посуды и теплообмена. Само слово «нейтрализация» не гарантирует pH 7 при любом избытке.'
],'Одинаковые количества HCl и NaOH расходуются 1:1. Если HCl было больше, после реакции останется кислотный избыток.','Нейтрализация — процесс; нейтральная среда — возможный, но не обязательный итог.','Сопоставьте выделение тепла, уравнение и конечный избыток.',[
 q('Что принимает основание Брёнстеда?',['Протон','Обязательно нейтрон'],0,['Это определение кислотно-основной пары.','Ядерные частицы здесь не переносятся.']),
 q('После добавления избытка кислоты к щёлочи pH обязан стать 7?',['Нет','Да'],0,['Избыток кислоты остаётся после расхода основания.','pH зависит от итогового состава.'])
],lab('Проведите виртуальную нейтрализацию',{kind:'pour',receiver:{kind:'beaker',substance:'naoh',volume:20},donor:{substance:'hcl',volume:20}},{type:'reaction',id:'neutralization'},['Добавляйте подготовленный раствор кислоты в щёлочь на виртуальном столе.','Найдите уравнение и проследите температуру и состав.'],'Модель зарегистрировала расход HCl и NaOH с образованием соли и воды.'),['phenolphthalein']);

lesson(17,4,'pH и язык индикаторов','Один цвет означает диапазон, а не точное число.',[
 'pH определяется через активность ионов водорода — безразмерную меру их эффективного участия в равновесиях. В разбавленном идеальном приближении используют численную концентрацию в моль/л: pH ≈ −log₁₀[H₃O⁺]. Изменение pH на единицу соответствует десятикратному изменению активности.',
 'Индикатор имеет несколько форм с разной окраской, соотношение которых зависит от среды. Фенолфталеин меняет цвет примерно в области pH 8,2–10. По розовому цвету нельзя определить, какая именно щёлочь находится в стакане.'
],'Два раствора NaOH и KOH могут давать сходный цвет фенолфталеина: индикатор отвечает на среду, а не на название катиона.','pH — логарифмическая величина; цвет индикатора — интервальная подсказка.','Запишите цвет, pH модели и то, чего индикатор определить не позволяет.',[
 q('При переходе от pH 4 к pH 3 активность H₃O⁺…',['Увеличивается в 10 раз','Увеличивается на одну частицу'],0,['Логарифмическая шкала связывает единицу с множителем 10.','pH не является прямым счётчиком частиц.']),
 q('Розовый фенолфталеин доказывает наличие именно NaOH?',['Нет','Да'],0,['Подходящую щелочную среду могут создать разные вещества.','Индикатор не является селективным тестом на натрий.'])
],lab('Добавьте индикатор',{kind:'pour',receiver:{kind:'beaker',substance:'naoh',volume:10},donor:{substance:'phenolphthalein',volume:2}},{type:'pour',substance:'phenolphthalein',minVolume:.2},['Перенесите небольшую часть раствора индикатора.','Сопоставьте изменение цвета с pH и составом.'],'Индикатор перенесён в щелочную среду. Его цвет — наблюдение, а численное pH остаётся приближением модели.'),['bromothymol_blue']);

lesson(18,4,'Сила кислоты и её запас','Слабая кислота не значит мало кислоты.',[
 'Сила кислоты описывает склонность отдавать протон в заданной среде. Диссоциация здесь — образование ионов при передаче протона воде; её равновесную степень характеризует константа Ka. Концентрация описывает количество на объём: слабая кислота может быть концентрированной.',
 'Равновесие означает баланс встречных процессов, а не их остановку. При нейтрализации слабой кислоты основание удаляет протоны, и диссоциация восполняет их. Поэтому можно израсходовать значительно больше кислоты, чем было диссоциировано в каждый отдельный момент.'
],'Уксусная кислота слабее HCl в воде, но 10 ммоль CH₃COOH всё равно требуют примерно 10 ммоль OH⁻ для полной нейтрализации.','Сила отвечает за равновесие, запас — за стехиометрический расход.','Разведите понятия «слабая», «разбавленная» и «малое количество».',[
 q('Слабую кислоту обязательно легко полностью нейтрализовать одной каплей?',['Нет, важен её общий запас','Да, слабость означает почти отсутствие вещества'],0,['Нужно учитывать количество кислоты, а не только её диссоциацию.','Слабость и количество не являются синонимами.']),
 q('Какова роль NaOH в реакции с CH₃COOH?',['Он принимает кислотные протоны','Он увеличивает число атомов углерода'],0,['Возникают ацетат и вода.','Атомы углерода не создаются основанием.'])
],lab('Получите ацетат',{kind:'pour',receiver:{kind:'beaker',substance:'acetic_acid',volume:20},donor:{substance:'naoh',volume:10}},{type:'reaction',id:'acetate'},['Добавьте часть щёлочи к слабой кислоте.','Убедитесь, что образуется ацетат и может оставаться исходная кислота.'],'Слабая кислота реагирует с основанием; слабость не исключает нейтрализацию.'),['potassium_hydroxide']);

lesson(19,4,'Буфер сопротивляется изменению','Почему небольшая добавка кислоты не всегда резко меняет pH?',[
 'Буфер содержит слабую кислоту и её сопряжённое основание в заметных количествах. Добавленный протон преимущественно связывается основной формой, а добавленная щёлочь расходует кислотную форму.',
 'Для удобства вводят pKa = −log₁₀Ka. В подходящем приближении pH = pKa + log₁₀([основание]/[кислота]). Буфер имеет конечную ёмкость: большой добавкой можно израсходовать одну форму. Формула не заменяет полный расчёт любой смеси.'
],'Для ацетатной пары с pKa ≈ 4,76 равные количества форм дают pH около 4,76. Десятикратный избыток основной формы повышает оценку примерно на единицу.','Буфер не фиксирует pH навсегда: его компоненты расходуются.','Опишите, какая форма буфера принимает добавленный протон.',[
 q('Какая смесь подходит для ацетатного буфера?',['CH₃COOH и CH₃COO⁻','Только вода и инертное стекло'],0,['Это слабая кислота и её сопряжённое основание.','Здесь нет достаточного запаса сопряжённой пары.']),
 q('Очень большая добавка сильной кислоты может исчерпать буфер?',['Да','Нет, pH никогда не изменится'],0,['Буферная ёмкость ограничена количеством компонентов.','Буфер не нарушает стехиометрию.'])
],calc('Оцените pH буфера','pKa = 4,76, отношение основной формы к кислотной равно 10. Оцените pH.',5.76,'pH','pH ≈ 4,76 + log₁₀10 = 5,76.',.02),['phosphoric_acid']);

lesson(20,4,'Несколько кислотных ступеней','Три протона не уходят с одинаковой лёгкостью.',[
 'Ортофосфорная кислота может последовательно отдавать три протона. Каждой ступени соответствует своя константа: после удаления первого протона оставшиеся обычно удерживаются сильнее.',
 'Добавление одного, двух или трёх эквивалентов основания приводит к разным суммарным формам. В воде они участвуют в равновесиях, поэтому формула соли не означает присутствия только одного вида фосфат-иона.'
],'H₃PO₄ + NaOH → NaH₂PO₄ + H₂O — первая ступень. Для последующих ступеней нужны дополнительные эквиваленты NaOH.','Число доступных протонов и сила каждой ступени — разные характеристики.','Нарисуйте цепочку H₃PO₄ → H₂PO₄⁻ → HPO₄²⁻ → PO₄³⁻.',[
 q('Один эквивалент NaOH на H₃PO₄ в суммарной записи прежде всего даёт…',['Дигидрофосфат','Сразу полностью нейтрализованный фосфат'],0,['Один протон заменён, два остаются.','Для полной суммарной нейтрализации нужны три эквивалента.']),
 q('Три ступени диссоциации обязаны иметь одинаковый Ka?',['Нет','Да'],0,['Заряд и окружение после каждой ступени меняются.','Многоосновность не означает одинаковую силу всех ступеней.'])
],lab('Начните фосфатную цепочку',{kind:'pour',receiver:{kind:'beaker',substance:'phosphoric_acid',volume:20},donor:{substance:'naoh',volume:8}},{type:'reaction',id:'phosphate_first'},['Добавьте щёлочь к подготовленной ортофосфорной кислоте.','Найдите в составе NaH₂PO₄ и отличите его от Na₃PO₄.'],'Первая ступень зарегистрирована; название продукта определяется реальным составом.'),['sulfuric_acid']);

lesson(21,5,'Как появляется осадок','Два раствора могут создать новую твёрдую фазу.',[
 'При смешивании растворов некоторые ионы образуют соединение, которое мало растворяется в этих условиях. Его выделение в отдельную твёрдую фазу называется осаждением. Осадок отличается от случайно внесённого нерастворимого порошка своим происхождением.',
 'Сам по себе обмен местами в записанной формуле не гарантирует реакцию. Для заметного итогового изменения важны образование малорастворимого продукта, газа или иной термодинамически выгодный процесс. В игре правила осаждения заданы явно.'
],'Cu²⁺ + 2OH⁻ → Cu(OH)₂(s). Голубой осадок возникает из ионов, ранее распределённых в растворе.','Ищите изменение состояния и состава, а не только перестановку символов.','Отличите осаждение нового вещества от добавления готового порошка.',[
 q('Осадок обязательно существовал в бутылке до смешивания?',['Нет, он может образоваться из растворённых ионов','Да'],0,['Это и есть смысл реакции осаждения.','Новая твёрдая фаза может возникнуть после смешивания.']),
 q('Любая пара растворимых солей обязательно даст видимую реакцию?',['Нет','Да, ионы всегда обязаны выпасть в осадок'],0,['Нужно учитывать растворимость и другие условия.','Многие смеси остаются растворами без заметного превращения.'])
],analysis('Признак новой фазы','После смешивания прозрачных растворов образовались голубые частицы. Какой вывод обоснован?',['Появилась твёрдая фаза; её состав ещё нужно установить','Доказано, что получилась металлическая медь'],0,'Осадок подтверждает новую фазу, но цвет сам по себе не доказывает металлическую медь.'),['cuso4']);

lesson(22,5,'Голубой гидроксид меди','Проверьте прогноз на конкретной системе.',[
 'Водный CuSO₄ даёт голубую окраску из-за гидратированных ионов меди(II). При добавлении NaOH в поддерживаемом опыте появляется Cu(OH)₂, а натрий и сульфат остаются в жидкой части.',
 'В результате получается смесь твёрдого гидроксида и раствора сопутствующей соли. Поэтому полное название содержимого должно включать больше одного продукта. Получить осадок и выделить чистый сухой продукт — разные задачи.'
],'CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄. Два эквивалента OH⁻ нужны на один Cu²⁺.','Осадок находится в маточном растворе, пока его не разделили с ним.','Запишите состав твёрдой и растворённой частей после опыта.',[
 q('Что остаётся в растворе после стехиометрического осаждения?',['Сопутствующая натриевая соль','Обязательно только чистая вода'],0,['Na⁺ и SO₄²⁻ не исчезают при осаждении меди.','Ионы сопутствующей соли сохраняются.']),
 q('На 1 ммоль CuSO₄ нужно по уравнению…',['2 ммоль NaOH','0,5 ммоль NaOH'],0,['Гидроксид содержит две группы OH.','Такого количества основания недостаточно.'])
],lab('Получите голубой осадок',{kind:'pour',receiver:{kind:'beaker',substance:'cuso4',volume:20},donor:{substance:'naoh',volume:16}},{type:'reaction',id:'copper_precipitate'},['Перелейте щёлочь в раствор сульфата меди.','Найдите Cu(OH)₂ и сопутствующую соль в составе.'],'Осаждение подтверждено. Смесь не обозначена как чистый гидроксид.'));

lesson(23,5,'Растворимость зависит от среды','Нерастворимое в воде не значит неизменное во всех условиях.',[
 'Растворимость относится к конкретному растворителю, температуре и химическому составу среды. Кислота может расходовать ионы, связанные с осадком, и тем самым способствовать его растворению.',
 'Карбонат кальция мало растворим в чистой воде, но с кислотой образует растворимую соль, CO₂ и воду. Это химическое растворение: твёрдая фаза исчезает не только потому, что её частицы физически распределились в воде.'
],'CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O. Кислота меняет карбонатную часть, а не просто окрашивает мел.','Утверждение «не растворяется» всегда требует указать среду.','Опишите, какие продукты объясняют исчезновение твёрдой фазы.',[
 q('Можно перенести растворимость в воде на кислую среду без проверки?',['Нет','Да'],0,['Кислота меняет химические равновесия и состав.','Смена среды может изменить результат.']),
 q('При реакции CaCO₃ с HCl углерод в основном переходит в…',['CO₂','Металлический кальций'],0,['Углерод остаётся в углекислом газе.','Кальций не содержит атомов углерода.'])
],lab('Измените среду твёрдого образца',{kind:'pour',receiver:{kind:'beaker',substance:'hcl',volume:20},donor:{substance:'calcium_carbonate',volume:.2}},{type:'reaction',id:'chalk_acid'},['В виртуальном опыте внесите часть карбоната в подготовленную кислоту.','Проследите газовыделение и образование CaCl₂.'],'Карбонат вступил в химическое превращение; сравнение с чистой водой имело бы иной результат.'),['iron3_oxide']);

lesson(24,5,'Сокращённое ионное уравнение','Какие участники действительно меняются?',[
 'Полное молекулярное уравнение удобно для общего состава, но не всегда показывает главных участников. В водной среде растворимые сильные электролиты можно представить ионами, а одинаковые ионы с обеих сторон сократить.',
 'Сокращённая запись должна сохранять не только атомы, но и электрический заряд. Нельзя раскладывать любой осадок на свободные ионы так, будто он полностью растворён. Агрегатные состояния здесь часть смысла уравнения.'
],'В CuSO₄ + 2NaOH → Cu(OH)₂↓ + Na₂SO₄ сокращаются Na⁺ и SO₄²⁻, остаётся Cu²⁺ + 2OH⁻ → Cu(OH)₂(s).','Проверяйте баланс атомов, заряда и фаз одновременно.','Сократите ионную запись нейтрализации HCl и NaOH.',[
 q('Ион-наблюдатель — это ион, который…',['Не меняется в данной суммарной реакции','Никогда ни с чем не реагирует'],0,['Роль относится к конкретному процессу.','В другой системе тот же ион может участвовать.']),
 q('Слева Cu²⁺ + 2OH⁻. Суммарный заряд равен…',['0','+4'],0,['+2 и два отрицательных единичных заряда взаимно компенсируются.','Знак OH⁻ нельзя игнорировать.'])
],analysis('Что сократить?','В нейтрализации HCl(aq) и NaOH(aq) какие ионы являются наблюдателями?',['Na⁺ и Cl⁻','H₃O⁺ и OH⁻'],0,'Протоны и гидроксид расходуются; натрий и хлорид остаются в растворе.'),['magnesium']);

lesson(25,5,'Маршрут между классами веществ','Соль, гидроксид и оксид могут быть звеньями одной истории.',[
 'Цепочка CuSO₄ → Cu(OH)₂ → CuO → CuCl₂ связывает осаждение, нагрев и кислотное растворение. В каждой стрелке свои условия; простая схема не заменяет уравнения и балансы.',
 'У настоящих растворов бывают дополнительные пути: комплексообразование, гидратация, конкурирующие осадки. Например, некоторые амфотерные гидроксиды растворяются в избытке щёлочи. Отсутствие такого правила в игре — граница модели, а не запрет природы.'
],'Чтобы исследовать CuO, его сначала получают из доступного соединения меди. Готовый продукт не должен появляться в опыте без объяснения происхождения.','Каждая стрелка схемы требует условий, уравнения и проверки состава.','Составьте карту одной цепочки и у каждой стрелки укажите тип превращения.',[
 q('Надпись A → B сама по себе задаёт реальную процедуру?',['Нет, нужны условия и химическое обоснование','Да, любое превращение происходит при смешивании'],0,['Стрелка обозначает гипотезу или сокращённый маршрут.','Реакции требуют определённых условий и иногда вовсе недоступны.']),
 q('Если игра не растворяет Zn(OH)₂ в избытке щёлочи, это доказывает невозможность процесса?',['Нет, это ограничение модели','Да'],0,['Модель не включает все реальные комплексные формы.','Отсутствующее правило не отменяет известную химию.'])
],analysis('Найдите недостающее условие','Ученик пишет Cu(OH)₂ → CuO и считает, что достаточно ждать при любой температуре. Что добавить?',['Условие нагревания и учёт выделившейся воды','Только изменить название бутылки'],0,'Это термическое превращение с продуктом H₂O, а не переименование объекта.'),['calcium_oxide']);

lesson(26,6,'Тепло и температура','Одинаковый нагреватель не даёт одинаковую скорость нагрева любому образцу.',[
 'Температура характеризует тепловое состояние, а тепло — передачу энергии из-за разности температур. Для простого нагрева без фазового перехода q ≈ mcΔT; большее количество вещества обычно требует больше энергии на то же ΔT.',
 'Часть энергии получает посуда, часть уходит в окружающую среду. В симуляторе эти эффекты приближённые и время ускорено. Сравнивать два опыта следует при одинаковых начальных условиях и геометрии установки.'
],'При одинаковой теплоёмкости и отсутствии потерь для нагрева 100 г воды на 10 °C нужно вдвое больше энергии, чем для 50 г.','Температура — не запас тепла; важны масса, теплоёмкость и условия передачи.','Нарисуйте направления передачи энергии между нагревателем, водой и комнатой.',[
 q('Одинаковая температура означает одинаковую энергию двух разных образцов?',['Нет','Да'],0,['Энергия зависит также от количества и свойств вещества.','Температура не задаёт общий запас энергии.']),
 q('В формуле q = mcΔT величина c — это…',['Удельная теплоёмкость','Молярная концентрация'],0,['Обозначения зависят от контекста; здесь речь о нагреве.','Концентрация не является коэффициентом этого уравнения.'])
],lab('Нагрейте воду до 50 °C',{kind:'heat',receiver:{kind:'beaker',substance:'water',volume:25},heater:'hotplate'},{type:'heat',substance:'water',minTemperature:50},['Включите подготовленную плитку и наблюдайте температуру воды.','После достижения цели выключите нагрев и проследите охлаждение.'],'Температура достигла порога. Время симулятора не является измеренной реальной скоростью нагрева.'));

lesson(27,6,'Экзотермический процесс','Реакция может сама нагреть окружающий раствор.',[
 'Энтальпия H — функция состояния: её изменение определяется начальным и конечным состояниями, а не выбранным путём. При постоянном давлении и только работе расширения ΔH связано с переданным теплом. Экзотермический процесс отдаёт тепло и имеет ΔH < 0; эндотермический поглощает его и имеет ΔH > 0.',
 'При гидратации CaO образуется Ca(OH)₂ и выделяется тепло. Заметность роста температуры зависит от количества воды и тепловых потерь. Нагрев раствора — признак энергетического изменения, но сам по себе не определяет структуру продукта.'
],'CaO + H₂O → Ca(OH)₂. Вода здесь не только среда: часть её химически расходуется.','Тепло реакции и температура образца связаны, но не являются одной величиной.','Отметьте, что в этом опыте вода одновременно делает как среда и как реагент.',[
 q('Для экзотермической реакции ΔH системы обычно…',['Отрицательно','Положительно'],0,['Система передаёт энергию в окружающую среду.','Положительный тепловой эффект соответствует поглощению тепла при данных условиях.']),
 q('В гидратации CaO вода…',['Участвует в уравнении реакции','Всегда остаётся полностью неизменной'],0,['Она входит в состав образующегося гидроксида.','Здесь вода не только пассивный растворитель.'])
],lab('Наблюдайте гидратацию',{kind:'pour',receiver:{kind:'beaker',substance:'water',volume:20},donor:{substance:'calcium_oxide',volume:.2}},{type:'reaction',id:'lime_slaking'},['Внесите виртуальный образец CaO в воду.','Проследите возникновение гидроксида и изменение температуры без включённой плитки.'],'Гидратация зарегистрирована. Изменение состава сопровождается выделением энергии.'));

lesson(28,6,'Кипение и скрытая теплота','Почему температура может почти перестать расти при продолжающемся нагреве?',[
 'Во время фазового перехода энергия может идти на изменение состояния вещества, а не только на рост температуры. При кипении чистой воды под постоянным внешним давлением температура остаётся около соответствующей точки кипения.',
 'Точка кипения зависит от давления и состава. Нелетучие компоненты не обязаны уходить вместе с водой; они остаются в остатке. В игре кипение воды описано приближённо, а летучесть кислот и других компонентов учтена не полностью.'
],'Кастрюля кипящей воды продолжает получать энергию, хотя термометр около 100 °C при обычном атмосферном давлении почти не меняется.','При фазовом переходе передача энергии не обязана повышать температуру.','Сравните изменение температуры и объёма до кипения и во время него.',[
 q('Кипящая вода получает энергию, но T почти постоянна. Энергия…',['Идёт в том числе на переход в газовую фазу','Исчезает'],0,['Энтальпия парообразования учитывает этот расход.','Сохранение энергии не перестаёт действовать.']),
 q('Вода всегда кипит ровно при 100 °C?',['Нет, важны давление и состав','Да, это не зависит от условий'],0,['100 °C — ориентир для чистой воды при определённом давлении.','Условия меняют температуру кипения.'])
],lab('Дождитесь кипения воды',{kind:'heat',receiver:{kind:'evaporating_dish',substance:'water',volume:10},heater:'hotplate'},{type:'boil',substance:'water'},['Включите подготовленный нагрев открытой чашки.','Дождитесь события кипения, затем сравните объём воды с исходным.'],'Событие кипения подтверждено расчётом фазы, а не только визуальным облаком.'));

lesson(29,6,'Энтропия и число возможностей','Почему слово «беспорядок» бывает слишком грубым?',[
 'Энтропия связана с числом микросостояний — способов распределить частицы и энергию, совместимых с наблюдаемыми величинами вроде температуры и объёма. Перераспределение энергии и частиц меняет это число. Простая картинка «аккуратно — неаккуратно» не охватывает физический смысл.',
 'Для самопроизвольного процесса учитывают изменение энтропии системы вместе с окружающей средой. Энтропия самой системы может уменьшаться, если компенсирующий вклад среды достаточно велик.'
],'При кристаллизации вода становится более упорядоченной на молекулярном уровне, но отданное среде тепло влияет на суммарный баланс энтропии.','Для второго начала важен общий баланс системы и среды.','Приведите пример уменьшения энтропии системы без нарушения второго начала.',[
 q('Самопроизвольность требует, чтобы энтропия только системы всегда росла?',['Нет','Да'],0,['Нужно учитывать систему и среду вместе.','Такое правило игнорирует тепловой обмен.']),
 q('Какая формулировка точнее?',['Энтропия связана с доступными микросостояниями','Энтропия — исключительно видимый беспорядок предметов'],0,['Это связывает макровеличину с микроскопическим описанием.','Визуальная метафора не является общим определением.'])
],analysis('Система и среда','В процессе ΔS системы = −20 Дж/К, ΔS среды = +35 Дж/К. Каков общий вывод?',['Суммарное изменение +15 Дж/К, оно допускает самопроизвольность','Процесс запрещён из-за отрицательного ΔS системы'],0,'Складываем оба вклада: −20 + 35 = +15 Дж/К. Один отрицательный вклад не решает всё.'));

lesson(30,6,'Энергия Гиббса и направление','Выгодно не значит быстро.',[
 'При постоянных температуре и давлении направление самопроизвольного изменения связано с уменьшением энергии Гиббса. Для процесса при заданной T используют ΔG = ΔH − TΔS, с температурой в кельвинах и согласованными единицами.',
 'Отрицательное ΔG не задаёт скорость: путь может иметь высокий барьер активации. Кроме того, стандартное ΔG° и текущее ΔG различаются; состав смеси входит в связь ΔG = ΔG° + RT ln Q.'
],'Процесс может быть термодинамически выгоден, но идти незаметно медленно. Катализатор меняет путь и скорость, не превращая ΔG° в другую величину.','Термодинамика предсказывает направление, кинетика — темп и путь.','Запишите два разных вопроса: «в какую сторону?» и «как быстро?».',[
 q('ΔG < 0 автоматически означает мгновенную реакцию?',['Нет','Да'],0,['Высокий барьер может тормозить выгодный процесс.','Скорость не определяется одним знаком ΔG.']),
 q('В ΔG = ΔH − TΔS температуру подставляют…',['В кельвинах','Всегда в градусах Цельсия без преобразования'],0,['Абсолютная температура необходима для термодинамической формулы.','Шкала Цельсия здесь даёт неверное произведение.'])
],calc('Согласуйте энергию и энтропию','ΔH = 10 кДж/моль, ΔS = 50 Дж/(моль·К), T = 300 К. Найдите ΔG в кДж/моль.',-5,'кДж/моль','50 Дж = 0,050 кДж; ΔG = 10 − 300·0,050 = −5 кДж/моль.',.01),['hydrogen_peroxide']);

lesson(31,7,'Что означает скорость реакции','Яркая вспышка и большой выход отвечают на разные вопросы.',[
 'Скорость описывает изменение количества или концентрации за время с учётом стехиометрии. Средняя скорость на интервале отличается от мгновенной; измерять только конечное количество продукта недостаточно для описания всего хода.',
 'На скорость влияют температура, концентрация, состояние поверхности и механизм. Сравнение металлов требует одинаковых условий, включая площадь поверхности. Игровые скорости ускорены, поэтому из времени анимации нельзя извлекать реальные константы.'
],'Если концентрация реагента уменьшилась на 0,60 моль/л за 30 с, средняя скорость его исчезновения равна 0,020 моль/(л·с).','Для скорости нужны и изменение, и интервал времени.','Опишите, что следовало бы держать одинаковым при сравнении железа и цинка.',[
 q('Один конечный выход полностью определяет скорость реакции?',['Нет, нужна информация о времени','Да'],0,['Одинаковый выход может быть достигнут за разные интервалы.','Выход и скорость — разные характеристики.']),
 q('Можно получить лабораторную константу скорости прямо из секунд игры?',['Нет, здесь скорости условно ускорены','Да, время анимации является эталоном'],0,['Кинетические коэффициенты симулятора не являются измеренными данными.','Модель рассчитана на наблюдение, а не метрологическую калибровку.'])
],lab('Проследите реакцию металла',{kind:'pour',receiver:{kind:'beaker',substance:'hcl',volume:20},donor:{substance:'zinc',volume:.05}},{type:'reaction',id:'zinc_acid'},['Внесите часть виртуальных гранул цинка в подготовленный раствор.','Запишите появление газа и изменение количества металла, не приравнивая игровое время к реальному.'],'Реакция цинка зарегистрирована. Для сравнения скоростей нужны контролируемые условия.'),['manganese_dioxide']);

lesson(32,7,'Катализатор меняет путь','Почему вещество помогает реакции, не расходуясь по суммарному уравнению?',[
 'Катализатор участвует в стадиях механизма, но регенерируется и не расходуется стехиометрически в суммарной реакции. Он предоставляет более быстрый путь с иной последовательностью энергетических барьеров.',
 'Катализатор не меняет равновесную константу и ΔG° данной реакции при той же температуре. Он ускоряет достижение равновесия, влияя на прямые и обратные пути. В поддерживаемом опыте MnO₂ ускоряет разложение H₂O₂.'
],'2H₂O₂ → 2H₂O + O₂. MnO₂ указывают как условие катализа, а не как расходуемый продукт этого суммарного уравнения.','Катализатор меняет кинетику, но не положение равновесия.','Сравните количество MnO₂ до и после; укажите, какой газ образовался.',[
 q('Хороший катализатор обязан увеличить K равновесия?',['Нет','Да'],0,['K при данной температуре определяется термодинамикой, а не скоростью пути.','Ускорение не означает изменение равновесного состава.']),
 q('В суммарном разложении H₂O₂ каталитический MnO₂…',['Сохраняется','Обязательно превращается весь в кислород'],0,['Катализатор регенерируется и остаётся в смеси.','Кислород образуется из пероксида.'])
],lab('Наблюдайте катализ',{kind:'pour',receiver:{kind:'beaker',substance:'hydrogen_peroxide',volume:20},donor:{substance:'manganese_dioxide',volume:.05}},{type:'reaction',id:'peroxide_catalysis'},['Добавьте виртуальный MnO₂ в подготовленный разбавленный пероксид.','Найдите кислород среди наблюдений и проверьте, что катализатор остаётся в составе.'],'Катализ зарегистрирован; состав подтверждает сохранение MnO₂.'));

lesson(33,7,'Порядок реакции находят по данным','Коэффициент уравнения не всегда равен степени в законе скорости.',[
 'Эмпирический закон скорости может иметь вид v = k[A]ᵐ[B]ⁿ. Показатели m и n определяют по эксперименту или обосновывают механизмом. Для общей многостадийной реакции их нельзя автоматически переписать из коэффициентов уравнения.',
 'Метод начальных скоростей сравнивает опыты, где меняют одну концентрацию при одинаковых остальных условиях. Если удвоение [A] увеличивает скорость в четыре раза, данные согласуются со вторым порядком по A на изученном диапазоне.'
],'Опыты: [A] = 0,10 → v = 0,002; [A] = 0,20 → v = 0,008 при одинаковой [B]. Отношение скоростей 4 = 2ᵐ, значит m = 2.','Стехиометрия задаёт баланс, закон скорости — проверяемую зависимость.','Запишите, какие условия должны совпадать в паре кинетических опытов.',[
 q('Можно всегда взять порядок из суммарного уравнения?',['Нет','Да'],0,['Такой вывод допустим лишь для определённой элементарной стадии, а не любого итогового уравнения.','Многостадийный механизм может дать другие показатели.']),
 q('Если [A] удвоили, а v не изменилась, наблюдаемый порядок по A…',['Нулевой в изученном диапазоне','Обязательно второй'],0,['Зависимость v от A в этой серии не обнаружена.','Второй порядок дал бы четырёхкратное изменение.'])
],calc('Определите порядок','Удвоение [A] при прочих равных увеличило начальную скорость в 4 раза. Найдите порядок по A.',2,'','4 = 2², значит порядок по A равен 2.',0));

lesson(34,7,'Динамическое равновесие','Неподвижный состав не означает остановку молекул.',[
 'В химическом равновесии прямой и обратный процессы продолжаются с одинаковыми скоростями. Макроскопический состав остаётся постоянным, но количества реагентов и продуктов вовсе не обязаны быть равны.',
 'Константа равновесия связывает активности участников при заданной температуре. Реакционный коэффициент Q имеет ту же форму, но вычисляется для текущего состояния. Сравнение Q с K помогает определить направление изменения.'
],'Для A ⇌ B при K = a(B)/a(A) = 4 равновесие благоприятствует B, но не означает отсутствия A или остановки обмена.','В равновесии равны скорости, а не обязательно концентрации.','Объясните, чем Q отличается от K, не меняя форму выражения.',[
 q('При равновесии [реагент] обязательно равно [продукт]?',['Нет','Да'],0,['Отношение задаёт K, которое не обязано равняться единице.','Равенство скоростей не требует одинаковых концентраций.']),
 q('Если Q < K для записанного прямого направления, система стремится…',['Увеличить Q образованием продуктов','Обязательно остановить все процессы'],0,['Превращение в прямом направлении приближает отношение к K.','Равновесие ещё не достигнуто.'])
],analysis('Равновесие или остановка?','Состав закрытой системы постоянен, но обмен частицами продолжается. Как это описать?',['Динамическое равновесие','Полное отсутствие любых микропроцессов'],0,'Постоянство макросостава совместимо с равными встречными скоростями.'));

lesson(35,7,'Возмущение равновесия','Удобное правило должно оставаться связано с Q и K.',[
 'При добавлении компонента меняется Q, и система реагирует так, чтобы снова удовлетворить равновесному соотношению. При фиксированной температуре простое изменение концентрации не создаёт новую константу K.',
 'Температура может менять саму K. Изменение давления влияет на газовые равновесия через активности; школьное правило «к меньшему числу молекул газа» требует, чтобы сравнивали подходящие газовые системы, а не любые реакции.'
],'В условной газовой системе A₂ ⇌ 2A уменьшение объёма при неизменной T повышает давление и обычно благоприятствует стороне A₂ с меньшим числом газовых частиц.','Изменение состава меняет Q; изменение температуры может менять K.','Для одного возмущения укажите, какая величина меняется первой: Q или K.',[
 q('Добавили реагент при постоянной T. K обязана измениться?',['Нет','Да'],0,['Прежде всего меняется текущее отношение активностей Q.','Константа при той же температуре сохраняется.']),
 q('При изменении температуры K может измениться?',['Да','Нет, K универсально неизменна'],0,['Температура влияет на термодинамический баланс.','K постоянна лишь для заданных условий, прежде всего температуры.'])
],analysis('Сжатие газовой системы','Для A₂(g) ⇌ 2A(g) сожмём идеализированную смесь при постоянной T. Какая сторона обычно получает преимущество?',['A₂, где меньше газовых частиц','2A, только потому что коэффициент больше'],0,'Сжатие увеличивает Q для диссоциации; смещение к A₂ уменьшает его до прежнего K.'));

lesson(36,8,'Окисление и восстановление','Движение электронов можно увидеть как выделение металла.',[
 'Окисление — отдача электронов, восстановление — их принятие. Степень окисления служит формальным учётом электронов в соединениях; она не всегда равна реальному локальному заряду атома.',
 'В реакции Fe с Cu²⁺ железо окисляется до Fe²⁺, а медь восстанавливается до металла. Сумма отданных и принятых электронов должна совпадать. Нельзя записать одну полуреакцию как замкнутый процесс без партнёра.'
],'Fe → Fe²⁺ + 2e⁻; Cu²⁺ + 2e⁻ → Cu. После сложения электроны сокращаются.','Окисление и восстановление идут совместно, с балансом электронов.','Укажите восстановитель, окислитель и две полуреакции опыта.',[
 q('В этой паре железо является…',['Восстановителем, отдающим электроны','Окислителем, принимающим электроны'],0,['Оно восстанавливает медь, само окисляясь.','Электроны принимает Cu²⁺.']),
 q('Два отданных электрона можно оставить без получателя в полном уравнении?',['Нет','Да'],0,['Для замкнутого баланса нужен процесс принятия электронов.','Суммарное уравнение должно быть сбалансировано.'])
],lab('Вытесните медь железом',{kind:'pour',receiver:{kind:'beaker',substance:'cuso4',volume:20},donor:{substance:'iron',volume:.05}},{type:'reaction',id:'iron_copper'},['Добавьте часть виртуального железа в раствор соли меди.','Найдите появление Cu и FeSO₄ в составе.'],'Перенос электронов проявился как образование металлической меди и соли железа.'));

lesson(37,8,'Гальванический элемент','Разделённые полуреакции могут выполнять электрическую работу.',[
 'В гальваническом элементе окисление и восстановление разделены по электродам. Электроны идут по внешней цепи, а перенос ионов внутри системы поддерживает электронейтральность. Без полного пути зарядов устойчивый ток прекращается.',
 'Анод всегда связан с окислением, катод — с восстановлением. Знаки электродов зависят от режима работы. Для табличных потенциалов восстановления E°элемента = E°катода − E°анода; потенциалы не умножают на коэффициенты электронного баланса.'
],'Если E°(Cu²⁺/Cu) = +0,34 В и E°(Zn²⁺/Zn) = −0,76 В, для цинк-медного элемента получается 1,10 В.','Запоминайте процесс на электроде, а не только его знак.','Нарисуйте два пути: электронный снаружи и ионный внутри элемента.',[
 q('На аноде происходит…',['Окисление','Всегда восстановление'],0,['Это определение анода для обоих режимов.','Восстановление происходит на катоде.']),
 q('При удвоении полуреакции её стандартный потенциал удваивается?',['Нет','Да'],0,['Потенциал — интенсивная величина.','Умножаются количества и энергии, но не табличный потенциал.'])
],calc('Разность потенциалов','Катод: +0,34 В, анод: −0,76 В; оба значения — потенциалы восстановления. Найдите E°элемента.',1.10,'В','E° = 0,34 − (−0,76) = 1,10 В.',.005));

lesson(38,8,'Уравнение Нернста','Напряжение зависит от состава, а не только от названий металлов.',[
 'При неравновесном составе потенциал реакции связан с активностями через E = E° − (RT/nF)ln Q. Здесь n — число электронов в сбалансированном превращении, а Q относится именно к этому уравнению.',
 'При 298 К для десятичного логарифма коэффициент RT ln10/F приблизительно равен 0,05916 В. Использовать это число при любой температуре или смешивать ln с log₁₀ нельзя. Для растворов замена активностей концентрациями является приближением.'
],'Для n = 2 и Q = 100 поправка при 298 К равна (0,05916/2)·2 = 0,05916 В.','Форма логарифма, температура и коэффициенты должны быть согласованы.','Укажите все допущения, скрытые в сокращённой формуле Нернста.',[
 q('Число 0,05916 В в десятичной форме относится…',['Примерно к 298 К','К любой температуре без изменений'],0,['Температура входит в RT/F.','Универсального температурно-независимого коэффициента здесь нет.']),
 q('Q строят для…',['Того же сбалансированного уравнения, что и n','Любой похожей записи без коэффициентов'],0,['Изменение записи меняет степени в Q и число электронов.','Несогласованные определения дадут неверный потенциал.'])
],calc('Нестандартный потенциал','При 298 К E° = 1,10 В, n = 2, Q = 100. Найдите E, используя 0,05916 В.',1.04084,'В','E = 1,10 − (0,05916/2)·log₁₀100 = 1,04084 В.',.003));

lesson(39,8,'Электролиз и количество электричества','Заряд можно перевести в число переданных электронов.',[
 'В электролизе внешний источник энергии поддерживает превращение, которое при данных условиях само не выполняло бы нужную электрическую работу. Процесс на аноде остаётся окислением, а на катоде — восстановлением.',
 'Количество электронов связано с зарядом: n(e⁻) = Q/F, где F ≈ 96485 Кл/моль. Чтобы найти количество продукта, учитывают число электронов на его формульную единицу и выход по току. Здесь мы разбираем данные, а не собираем реальную установку.'
],'Для Cu²⁺ + 2e⁻ → Cu один моль электронов даёт максимум половину моля меди при 100 % выходе по току.','Заряд считает электроны; стехиометрия связывает их с продуктом.','Объясните, чем процентный выход продукта отличается от выхода по току.',[
 q('Для осаждения 1 моль Cu из Cu²⁺ нужно…',['2 моль электронов','0,5 моль электронов'],0,['Каждый Cu²⁺ принимает два электрона.','Это обратное отношение.']),
 q('Все электроны всегда идут только на один желаемый продукт?',['Нет, возможны конкурирующие процессы','Да'],0,['Поэтому вводят выход по току.','Побочные электродные реакции могут расходовать заряд.'])
],calc('Количество меди по заряду','Прошло 96485 Кл. Для Cu²⁺ + 2e⁻ → Cu примите выход по току 100 %. Сколько моль Cu возможно?',.5,'моль','Заряд соответствует 1 моль e⁻, значит Cu образуется 1/2 = 0,5 моль.',.001));

lesson(40,8,'Коррозия как система процессов','Почему ржавление — больше, чем встреча железа с водой?',[
 'Коррозия металла включает анодные и катодные участки, перенос зарядов и влияние среды. Влажность, кислород, электролит и контакт разных материалов могут менять скорость и путь процесса.',
 'Защита может мешать доступу среды, изменять электрохимическую пару или использовать более активный материал как расходуемый анод. Её выбор зависит от условий. В текущем игровом движке атмосферная коррозия полностью не рассчитывается.'
],'Покрытие изолирует поверхность, но царапина меняет условия. Электрохимическая защита и барьерная защита работают по разным принципам.','Коррозию объясняют цепью связанных процессов, а не одним словом «вода».','Предложите два разных принципа защиты и укажите, что каждый изменяет.',[
 q('Барьерное покрытие прежде всего…',['Ограничивает контакт металла со средой','Меняет число протонов в железе'],0,['Это физическое ограничение доступа участников процесса.','Химическая защита не изменяет элемент таким способом.']),
 q('Нет ржавчины в игре — значит в реальности выбранная пара не корродирует?',['Нет','Да'],0,['Атмосферная коррозия находится за границей этого движка.','Неполная модель не является испытанием реального материала.'])
],analysis('Выберите корректный вывод','В виртуальном опыте железо с водой не изменилось за минуту. Что можно утверждать?',['В этом сценарии модель не показала превращение','Железо никогда не корродирует в воде и воздухе'],0,'Результат ограничен возможностями модели, временем и условиями наблюдения.'));

lesson(41,9,'Углеродный скелет','Одинаковые атомы можно соединить множеством способов.',[
 'Органическая химия изучает огромное семейство соединений углерода, особенно структуры со связями C–C и C–H. Граница исторически условна: CO₂ и карбонаты обычно рассматривают в неорганической химии, хотя они содержат углерод.',
 'Структурная формула сообщает, какие атомы соединены и какими связями. Валентность описывает число образованных связей с учётом кратности. В обычных нейтральных органических структурах углерод часто четырёхвалентен; заряженные и радикальные частицы требуют отдельного рассмотрения.'
],'C₂H₆O может описывать этанол или диметиловый эфир. Одной молекулярной формулы недостаточно, чтобы узнать расположение связей.','Состав молекулы не определяет её строение однозначно.','Запишите, какую информацию даёт молекулярная формула и чего в ней не видно.',[
 q('Любое соединение углерода обязательно относят только к органической химии?',['Нет, классификация имеет условные границы','Да'],0,['Карбонаты и CO₂ — привычные неорганические примеры.','Наличие углерода само по себе не решает историческую классификацию.']),
 q('C₂H₆O однозначно задаёт структуру?',['Нет','Да'],0,['Возможны разные способы соединить те же атомы.','Нужна структурная информация.'])
],analysis('Формула и строение','Два образца имеют формулу C₂H₆O, но разные связи между атомами. Как их описать?',['Разные соединения с одинаковым составом','Один и тот же образец при любой структуре'],0,'Молекулярная формула совпадает, но различие связности создаёт разные вещества.'),['glucose']);

lesson(42,9,'Функциональные группы','Какая часть молекулы помогает предсказать тип реакции?',[
 'Функциональная группа — структурный фрагмент, связанный с характерными свойствами и превращениями. Гидроксильная, карбонильная и карбоксильная группы различаются; наличие кислорода ещё не делает все молекулы химически похожими.',
 'Карбоксильная группа —COOH может отдавать протон с образованием карбоксилата. Уксусная кислота удобна как мост между общей кислотно-основной химией и органическим строением. Соседние группы могут изменять силу кислоты.'
],'CH₃COOH + OH⁻ → CH₃COO⁻ + H₂O. Углеродный скелет сохраняется, а кислотная форма переходит в сопряжённое основание.','Тип группы и её окружение вместе влияют на свойства.','Выделите карбоксильную группу в уксусной кислоте и покажите изменение при нейтрализации.',[
 q('Карбоксильная группа записывается как…',['—COOH','Любой атом O без окружения'],0,['Она включает карбонильный и гидроксильный фрагменты в определённой связности.','Окружение кислорода принципиально важно.']),
 q('При нейтрализации уксусной кислоты обязательно разрушается углеродный скелет?',['Нет','Да'],0,['Здесь происходит перенос протона.','Данная реакция не требует разрыва C–C связи.'])
],lab('Проследите карбоксильную группу',{kind:'pour',receiver:{kind:'flask',substance:'acetic_acid',volume:15},donor:{substance:'naoh',volume:15}},{type:'reaction',id:'acetate'},['Проведите поддерживаемую нейтрализацию в виртуальной колбе.','Объясните изменение CH₃COOH → CH₃COO⁻ на уровне функциональной группы.'],'Тот же опыт получил структурное объяснение: изменилась кислотная форма органической группы.'));

lesson(43,9,'Изомерия: связь и пространство','Различие может быть скрыто даже при одинаковой связности.',[
 'Конституционные изомеры различаются порядком соединения атомов. Стереоизомеры имеют одинаковую связность, но различаются пространственным расположением. Конформации переходят друг в друга при обычном вращении связей; конфигурационное различие таким вращением не устраняется.',
 'Тетраэдрический атом углерода с четырьмя разными заместителями может быть стереогенным центром. Зеркальные формы иногда по-разному взаимодействуют с хиральной средой, например с белком. Определять такое различие по одной общей формуле нельзя.'
],'В CH₃–CH(OH)–CH₂–CH₃ центральный CH связан с H, OH, CH₃ и CH₂CH₃ — четырьмя разными группами.','Различайте состав, связность, конфигурацию и конформацию.','Составьте короткую таблицу трёх видов структурного различия.',[
 q('Этанол и диметиловый эфир с формулой C₂H₆O — это…',['Конституционные изомеры','Только две позы одной молекулы'],0,['У них различается связность атомов.','Вращением связей этанол не превращается в эфир.']),
 q('Любое вращение вокруг одинарной связи создаёт новый конфигурационный изомер?',['Нет','Да'],0,['Обычно это изменение конформации.','Конфигурационное различие нельзя так свободно устранить.'])
],analysis('Найдите возможный стереоцентр','Сравните CH₃–CH(OH)–CH₃ и CH₃–CH(OH)–CH₂CH₃. У какого центральный C имеет четыре разных заместителя?',['У второго','У первого'],0,'У первого есть две одинаковые группы CH₃; у второго заместители различаются.'));

lesson(44,9,'Механизм и электронные стрелки','Уравнение показывает итог, механизм — предполагаемый путь.',[
 'Механизм описывает последовательность стадий, изменения связей и промежуточные частицы. Изогнутая стрелка с полной головкой обычно обозначает движение электронной пары; стрелка с половинной головкой — одного электрона.',
 'Стрелка начинается там, где находятся электроны: на связи или неподелённой паре. Красивый рисунок механизма не доказывает его правильность. Его проверяют данными о скорости, изотопных эффектах, продуктах и промежуточных частицах.'
],'При переносе протона от кислоты к основанию одна стрелка идёт от пары основания к H, другая — от разрываемой связи H–A к A.','Механизм должен согласовывать электронный учёт и наблюдаемые данные.','Нарисуйте перенос протона и подпишите источник каждой электронной пары.',[
 q('Откуда начинается обычная стрелка электронной пары?',['От пары электронов или связи','Обязательно от положительного заряда'],0,['Стрелка показывает источник и направление движения электронов.','Положительный центр часто является принимающим участком.']),
 q('Одного правдоподобного рисунка достаточно, чтобы доказать механизм?',['Нет','Да'],0,['Нужна согласованность с независимыми данными.','Разные механизмы могут давать похожий общий итог.'])
],analysis('Проверьте стрелку','Основание отдаёт электронную пару протону. Где должна начинаться стрелка?',['На электронной паре основания','На самом протоне'],0,'Источник электронной пары находится у основания; протон принимает её в новую связь.'));

lesson(45,9,'Спектр как ограничение структуры','Один пик редко раскрывает целую молекулу.',[
 'Спектроскопия изучает взаимодействие вещества с излучением и переходы между разрешёнными уровнями энергии. ИК означает инфракрасную область и помогает распознавать колебания групп. ЯМР — ядерный магнитный резонанс — исследует окружение ядер; масс-спектрометрия отдельно анализирует массы и фрагменты ионов.',
 'Надёжная идентификация объединяет несколько независимых признаков. Отсутствие или наличие одной полосы ограничивает варианты, но не всегда выбирает единственный. В этом уроке анализируются условные данные, приборы в игре не имитируются.'
],'Сильная полоса около 1700 см⁻¹ совместима с карбонильной группой. Дополнительные полосы и другие методы нужны, чтобы различить возможные классы и структуры.','Спектральный признак — свидетельство, которое нужно сопоставить с альтернативами.','Запишите, какие данные помогли бы отличить два соединения с одной карбонильной группой.',[
 q('Одна полоса C=O однозначно задаёт всю структуру?',['Нет','Да'],0,['Карбонильная группа встречается у разных классов веществ.','Для полной идентификации информации недостаточно.']),
 q('Зачем объединять ИК и ЯМР данные?',['Они накладывают разные ограничения на структуру','Чтобы заменить проверку одинаковыми копиями одного результата'],0,['Разные методы дополняют друг друга.','Ценность именно в независимой информации.'])
],analysis('Осторожное заключение','В условном ИК-спектре видна полоса, характерная для C=O. Какой вывод корректен?',['Карбонильная группа вероятна; точная структура ещё не установлена','Это обязательно уксусная кислота'],0,'Карбонил есть в нескольких классах соединений, поэтому конкретное название пока не следует.'));

lesson(46,10,'Углеводы: формула и форма','Глюкоза — не просто число атомов углерода.',[
 'Углеводы объединяют соединения с определёнными структурными особенностями и их производные. У глюкозы формула C₆H₁₂O₆, но в воде она существует преимущественно в циклических формах, связанных с открытой формой равновесием.',
 'Формула не показывает пространственное расположение OH-групп и распределение форм. Эти различия важны для распознавания ферментами — биологическими катализаторами. В модели глюкоза представлена одним компонентом: отдельные циклические формы, брожение и сложные биохимические пути не рассчитываются.'
],'Раствор глюкозы может быть прозрачным, как раствор соли, однако это не означает одинаковых частиц или свойств.','Одна суммарная формула может скрывать несколько структурных форм в растворе.','Отметьте, какую информацию о глюкозе показывает игра и какую она объединяет в одну запись.',[
 q('Панель с C₆H₁₂O₆ показывает точное распределение циклических форм?',['Нет','Да'],0,['Движок хранит обобщённый компонент глюкозы.','Одной формулы недостаточно для описания пространственных форм.']),
 q('Прозрачность раствора глюкозы доказывает, что он аналогичен NaCl по частицам?',['Нет','Да'],0,['Внешний вид не определяет природу растворённых частиц.','Молекулярный и ионный растворы могут выглядеть сходно.'])
],lab('Рассмотрите органический раствор',{kind:'inspect',receiver:{kind:'beaker',substance:'glucose',volume:20}},{type:'inspect',substance:'glucose'},['Выберите подготовленный раствор глюкозы.','Сравните состав с раствором соли и запишите, какие биохимические свойства здесь не моделируются.'],'Глюкоза обнаружена в составе; осмотр не выдаёт несуществующих данных о её пространственных формах.'));

lesson(47,10,'Белок: последовательность и сворачивание','Почему одна цепь может иметь сложную функцию?',[
 'Аминокислоты содержат аминную и карбоксильную группы. В белках их остатки соединены пептидными фрагментами —C(=O)—N—. Последовательность остатков задаёт первичную структуру; дальнейшее сворачивание связано с множеством взаимодействий и условиями среды.',
 'Денатурация означает нарушение характерной пространственной организации и часто функции. Она не равна обязательному разрыву всех пептидных связей. Некоторые изменения обратимы, другие приводят к агрегации и необратимой потере исходного состояния.'
],'При изменении температуры белок может потерять активность, хотя основная последовательность аминокислот ещё сохранена.','Потеря формы и разрыв полимерной цепи — разные процессы.','Разведите термины «денатурация», «гидролиз пептидной связи» и «агрегация».',[
 q('Первичная структура белка — это…',['Последовательность аминокислотных остатков','Только внешний цвет раствора'],0,['Она описывает порядок звеньев цепи.','Цвет не задаёт последовательность.']),
 q('Денатурация обязательно означает распад всех пептидных связей?',['Нет','Да'],0,['Часто меняется сворачивание без полного гидролиза цепи.','Это смешение разных уровней структурных изменений.'])
],analysis('Что следует из потери активности?','Белок перестал работать после изменения среды. Какой вывод пока слишком сильный?',['Все пептидные связи разрушены','Пространственная организация могла измениться'],0,'Потеря функции не доказывает полный разрыв цепи; нужны дополнительные данные.'));

lesson(48,10,'Ферменты и насыщение','Биологический катализ подчиняется тем же физическим ограничениям.',[
 'Фермент — биологический катализатор; субстрат — вещество, которое он превращает. Активный центр представляет область связывания и катализа. Её строение и динамика определяют специфичность. Как любой катализатор, фермент не меняет K при той же температуре.',
 'Для некоторых начальных условий подходит модель Михаэлиса–Ментен: v = Vmax[S]/(Km + [S]). При большом [S] скорость приближается к Vmax, потому что ограничен доступный фермент. Эта формула не описывает автоматически все ферментные механизмы.'
],'Если [S] = Km, формула даёт v = Vmax/2. Km имеет размерность концентрации, а Vmax — скорости.','Насыщение отражает ограниченность каталитических центров, а не изменение равновесия.','Укажите условия, при которых простая ферментная модель может не подходить.',[
 q('Фермент обязан менять равновесный состав только потому, что он биологический?',['Нет','Да'],0,['Он меняет кинетику, а не термодинамическую константу.','Биологическое происхождение не отменяет термодинамику.']),
 q('При [S] = Km модель даёт…',['Половину Vmax','Обязательно нулевую скорость'],0,['Подстановка даёт Km/(Km+Km) = 1/2.','Нулю скорость соответствует другая ситуация, например отсутствие субстрата.'])
],calc('Скорость ферментной модели','Vmax = 12 мкмоль/мин, Km = 2 ммоль/л, [S] = 2 ммоль/л. Найдите v.',6,'мкмоль/мин','v = 12·2/(2+2) = 6 мкмоль/мин.',.01));

lesson(49,10,'Полимер — множество длин','Почему у пластика часто нет одной молярной массы?',[
 'Полимер содержит множество повторяющихся звеньев; исходные небольшие молекулы для построения цепи называют мономерами. Цепи образуются разными путями: в одних сохраняется состав мономера, в других при соединении функциональных групп отделяется небольшая молекула.',
 'Реальный образец обычно имеет распределение длин цепей, поэтому используют средние молярные массы и характеристики распределения. Разветвление, сшивки и порядок укладки влияют на механические свойства даже при сходной химии звеньев.'
],'Для условной цепи из 1000 звеньев —CH₂—CH₂— с массой звена около 28 г/моль оценка без концевых групп равна 28 000 г/моль.','Длина, распределение цепей и архитектура дополняют формулу звена.','Запишите три особенности полимера, которые не видны в формуле одного повторяющегося звена.',[
 q('Одинаковая формула звена гарантирует одинаковые свойства всех полимерных образцов?',['Нет','Да'],0,['Длина, разветвление и структура материала тоже важны.','Формула звена не описывает всю архитектуру.']),
 q('При оценке M цепи как N·Mзвена мы…',['Пренебрегаем концевыми группами и распределением','Доказываем точную массу любой молекулы образца'],0,['Это оговорённое упрощение расчёта.','Средняя или приближённая оценка не заменяет распределение масс.'])
],calc('Оцените массу цепи','Условная цепь имеет 1000 звеньев по 28 г/моль. Пренебрегите концевыми группами и найдите M.',28000,'г/моль','M ≈ 1000·28 = 28 000 г/моль.',1));

lesson(50,10,'Структура материала и задача','У полезного свойства всегда есть контекст применения.',[
 'Свойства материала зависят от состава, связи, структуры и дефектов. В кристаллическом состоянии есть дальний периодический порядок, в аморфном его нет. Эти формы могут различаться при близком элементном составе. Для выбора материала важно понимать конкретные условия службы.',
 'Диоксид кремния показывает, что не каждый образец должен бурно реагировать при смешивании. Его устойчивость в выбранной среде сама является наблюдением. Но неизменность в одной пробе не доказывает универсальную химическую инертность.'
],'Сравнивая материал для окна и для электрода, исследователь задаёт разные критерии: прозрачность, проводимость, прочность и устойчивость не взаимозаменяемы.','Свойство оценивают относительно задачи и условий, а не как абсолютное достоинство.','Выберите материал для воображаемого прибора и перечислите необходимые свойства.',[
 q('Одинаковый элементный состав всегда означает одинаковую структуру материала?',['Нет','Да'],0,['Возможны разные укладки, фазы и дефекты.','Состав не задаёт полностью пространственную организацию.']),
 q('Отсутствие изменений SiO₂ в воде доказывает его инертность в любых условиях?',['Нет','Да'],0,['Вывод ограничен средой и условиями испытания.','Другие условия могут открыть иные пути превращения.'])
],lab('Рассмотрите сетчатый образец',{kind:'inspect',receiver:{kind:'beaker',substance:'silica',volume:.3}},{type:'inspect',substance:'silica'},['Осмотрите виртуальный образец SiO₂ и прочитайте его свойства.','Сформулируйте ограниченный вывод о поддерживаемом поведении, не распространяя его на все условия.'],'Исходный образец изучен. Отсутствие реакции тоже требует аккуратной формулировки вывода.'));

lesson(51,11,'Измерение и неопределённость','Последняя цифра не появляется из уверенности исследователя.',[
 'Результат измерения включает значение, единицу и оценку неопределённости — диапазона, характеризующего доступное знание о величине. Разброс повторов показывает лишь часть возможных источников неопределённости.',
 'Случайные колебания и систематическое смещение различаются. Повторение измерений может уменьшить неопределённость среднего из-за случайных факторов, но не исправит неверную калибровку. При записи результата число значащих цифр должно соответствовать точности данных.'
],'При V = 10,0 ± 0,2 мл относительная оценка составляет 0,2/10,0 = 0,02, то есть 2 %. Прибор с постоянным сдвигом может давать очень близкие, но неверные значения.','Малый разброс не доказывает отсутствие систематической ошибки.','Назовите случайный и систематический источник ошибки при измерении объёма.',[
 q('Десять одинаковых показаний гарантируют правильную калибровку?',['Нет','Да'],0,['Общее смещение может сохраняться во всех повторах.','Согласованность повторов не равна истинности значения.']),
 q('Неопределённость следует записывать…',['Вместе со значением и единицей','Только если результат не понравился'],0,['Это часть характеристики измерения.','Выборочное указание неопределённости искажает отчёт.'])
],calc('Относительная неопределённость','Объём 10,0 мл, абсолютная оценка ±0,2 мл. Найдите относительную оценку в процентах.',2,'%','0,2 / 10,0 · 100 % = 2 %. ',.01));

lesson(52,11,'Титрование: событие и критерий','Момент изменения цвета не всегда совпадает с расчётной эквивалентностью.',[
 'Титрование определяет количество компонента по измеренному расходу реагента известной концентрации. Точка эквивалентности задаётся стехиометрией; конечная точка — наблюдаемым критерием, например сменой цвета индикатора.',
 'Подходящий индикатор выбирают по области резкого изменения pH, а не по красоте цвета. В виртуальном мини-опыте мы регистрируем нейтрализацию, но не выдаём её начало за точное титрование: для количественного вывода нужны объёмы и корректный критерий окончания.'
],'Для одноосновной кислоты и OH⁻ в отношении 1:1 при эквивалентности n(кислоты) = n(основания). До и после этой точки возможны разные избытки.','Эквивалентность — расчётный баланс; конечная точка — выбранное наблюдение.','Сформулируйте, какие измерения нужны, чтобы превратить демонстрацию в титрование.',[
 q('Начало реакции нейтрализации уже означает точку эквивалентности?',['Нет','Да'],0,['Реакция начинается задолго до полного стехиометрического расхода.','Нужно учесть суммарные количества, а не первое событие.']),
 q('Индикатор для титрования выбирают прежде всего по…',['Подходящему диапазону перехода','Самому яркому доступному цвету'],0,['Диапазон должен соответствовать требуемому участку кривой.','Яркость не гарантирует правильный критерий.'])
],lab('Отделите реакцию от конечной точки',{kind:'pour',receiver:{kind:'flask',substance:'hcl',volume:20},donor:{substance:'naoh',volume:20}},{type:'reaction',id:'neutralization'},['Добавьте часть основания и дождитесь первого события нейтрализации.','Объясните в заметке, почему это ещё не подтверждает эквивалентность и какое измерение требуется.'],'Начало процесса зарегистрировано; количественный вывод требует дополнительных данных об объёме и концентрации.'));

lesson(53,11,'Спектрофотометрия и калибровка','Цвет можно связать с концентрацией, если проверить модель.',[
 'Оптическая плотность A = −log₁₀(I/I₀) описывает ослабление проходящего света. В подходящем диапазоне закон Бугера–Ламберта–Бера даёт A = εlc, где l — длина пути света, c — концентрация, ε — молярный коэффициент поглощения.',
 'Реальная методика требует холостой пробы, калибровки и проверки линейности. Рассеяние на осадке, постороннее поглощение или слишком концентрированный раствор нарушают простую связь. Здесь решается задача по данным, а не моделируется готовый спектрофотометр.'
],'Если ε = 100 л/(моль·см), l = 1 см и c = 0,002 моль/л, ожидается A = 0,20 в условиях применимости закона.','Линейная формула полезна только после проверки диапазона и помех.','Запишите, какую роль играют холостая проба и калибровочный ряд.',[
 q('Осадок может мешать простой оценке концентрации по пропусканию света?',['Да, он рассеивает свет','Нет, прибор всегда видит только нужное вещество'],0,['Ослабление луча может быть связано не только с поглощением аналита.','Селективность и помехи нужно проверять.']),
 q('При фиксированных ε и l в линейном диапазоне удвоение c…',['Удваивает A','Обязательно уменьшает A вдвое'],0,['Это следует из A = εlc.','В данном диапазоне зависимость прямая.'])
],calc('Оптическая плотность','ε = 100 л/(моль·см), l = 1 см, c = 0,002 моль/л. Найдите A.',.2,'','A = 100·1·0,002 = 0,20.',.001));

lesson(54,11,'Разделение хроматографией','Компоненты могут двигаться с разной скоростью без превращения друг в друга.',[
 'Хроматография разделяет вещества благодаря разному взаимодействию с подвижной и неподвижной фазами. Компонент, сильнее задерживаемый неподвижной фазой в данных условиях, обычно продвигается медленнее.',
 'Для плоской хроматографии Rf — отношение пути центра пятна к пути фронта растворителя от одной стартовой линии. Сравнивать Rf имеет смысл при согласованных условиях. Совпадение одного показателя не является абсолютным доказательством идентичности.'
],'Пятно прошло 2,4 см, фронт — 6,0 см: Rf = 0,40. Этот результат относится к конкретным фазам и условиям опыта.','Разделение и химическая реакция — разные процессы; Rf зависит от методики.','Перечислите условия, которые нужно сохранить для сравнения двух хроматограмм.',[
 q('Для Rf оба расстояния измеряют…',['От одной стартовой линии','От разных удобных точек'],0,['Общий отсчёт необходим для осмысленного отношения.','Произвольные начала искажают Rf.']),
 q('Одинаковый Rf всегда доказывает, что вещества одинаковы?',['Нет','Да'],0,['Нужны дополнительные признаки и контроль условий.','Разные вещества могут случайно иметь близкие значения.'])
],calc('Рассчитайте Rf','Центр пятна прошёл 2,4 см, фронт растворителя — 6,0 см. Найдите Rf.',.4,'','Rf = 2,4 / 6,0 = 0,40.',.001));

lesson(55,11,'План опыта до первого действия','Какие данные смогут различить ваши объяснения?',[
 'План эксперимента задаёт изменяемые факторы, наблюдаемый отклик, контроль и повторения. Если одновременно менять температуру и концентрацию, различие скорости нельзя уверенно приписать только одному из них.',
 'Рандомизация порядка помогает не перепутать изучаемый фактор с дрейфом времени или прибора. Повторения позволяют оценить разброс. Более сложный факторный план исследует несколько факторов системно, а не просто меняет всё сразу.'
],'Один раствор измеряли утром холодным, другой вечером тёплым. Изменились сразу температура, время и, возможно, состояние прибора — причинный вывод ослаблен.','Хороший план превращает вопрос в сравнение с понятными альтернативами.','Опишите фактор, отклик, контроль, порядок измерений и повторения для одного опыта.',[
 q('Одновременно изменили концентрацию и температуру. Можно ли сразу выделить эффект температуры?',['Нет','Да'],0,['Эффекты смешаны, нужен другой план или дополнительные данные.','Одно сравнение не разделяет два изменения.']),
 q('Зачем случайно менять порядок измерений?',['Чтобы ослабить связь фактора с дрейфом во времени','Чтобы скрыть условия от собственного журнала'],0,['Это уменьшает риск систематического смешения причин.','Условия всё равно должны быть полностью записаны.'])
],analysis('Найдите смешение факторов','Образец A холодный и разбавленный, B тёплый и концентрированный. B реагирует быстрее. Какой вывод допустим?',['В этих двух условиях скорость различалась; вклад каждого фактора пока не разделён','Температура полностью объясняет разницу'],0,'Оба фактора менялись одновременно, поэтому их отдельные влияния ещё не установлены.'));

lesson(56,12,'Читать источник как исследователь','Ссылка — начало проверки, а не конец.',[
 'Первичная научная работа сообщает собственные методы, данные и выводы. Обзор объединяет несколько работ; учебник выстраивает проверенное объяснение темы. Эти источники выполняют разные функции и требуют разного способа чтения.',
 'Проверяйте, соответствуют ли условия статьи вашему вопросу, как измерялся результат и какие ограничения признают авторы. DOI помогает идентифицировать публикацию, но не является знаком безошибочности. Пересказ, включая ответ модели, нужно сверять с источником.'
],'Статья о концентрированном растворе при высокой температуре не автоматически подтверждает поведение разбавленного раствора при комнатных условиях.','Оценка источника включает происхождение, методы, условия и границы вывода.','Создайте карточку источника: вопрос, метод, ключевой результат, ограничение и ссылка.',[
 q('Наличие DOI гарантирует правильность всех выводов?',['Нет','Да'],0,['Идентификатор помогает найти работу, но не заменяет критическое чтение.','Ошибки и ограничения встречаются и в индексируемых публикациях.']),
 q('Чем полезен обзор?',['Он сопоставляет несколько исследований','Он всегда заменяет чтение методов первичной работы'],0,['Обзор помогает увидеть контекст и разногласия.','Для конкретного метода и данных может понадобиться оригинальная статья.'])
],analysis('Сила ссылки','Автор сослался на статью, но в ней использованы другие растворитель и температура. Что сделать?',['Проверить, переносим ли вывод на наши условия','Принять вывод только из-за наличия ссылки'],0,'Релевантность условий — часть проверки; формального совпадения ключевых слов недостаточно.'));

lesson(57,12,'Данные, разброс и честная обработка','Числа не должны подстраиваться под ожидаемую историю.',[
 'Сохраняйте исходные данные отдельно от расчётов и итоговых графиков. Среднее описывает центр ряда, но не показывает само по себе разброс или систематическую ошибку. Единицы, условия и правила обработки должны сопровождать значения.',
 'Необычное значение нельзя удалять только потому, что оно портит ожидаемый результат. Сначала проверяют запись, прибор, условия и заранее выбранные критерии. Если исключение обосновано, в отчёте сохраняют причину и показывают влияние на вывод.'
],'Ряд 9,8; 10,0; 10,2 даёт среднее 10,0. Этот расчёт не доказывает, что калибровка верна или что будущий опыт даст точно 10,0.','Сохраняйте след обработки: от исходного наблюдения до вывода.','Опишите правило работы с подозрительным измерением до просмотра желаемого результата.',[
 q('Можно удалить точку лишь потому, что она противоречит гипотезе?',['Нет','Да'],0,['Это искажает данные и мешает проверке гипотезы.','Гипотеза должна выдерживать данные, а не наоборот.']),
 q('Одно среднее достаточно для полного описания серии?',['Нет, нужны разброс и условия','Да'],0,['Ряды с одинаковым средним могут сильно различаться.','Среднее скрывает важную часть информации.'])
],calc('Среднее трёх наблюдений','Найдите среднее значений 9,8; 10,0; 10,2.',10,'','(9,8 + 10,0 + 10,2)/3 = 10,0.',.001));

lesson(58,12,'Воспроизводимость начинается с записи','Сможет ли другой человек понять, что именно было сделано?',[
 'Повторение в близких условиях помогает оценить устойчивость результата. Проверка при изменённых лабораториях, операторах или методах отвечает на более широкий вопрос воспроизводимости. Значения терминов могут уточняться конкретным стандартом, поэтому условия сравнения лучше писать явно.',
 'Протокол должен хранить состав исходных образцов, порядок действий, наблюдения, критерий окончания и способ обработки. В игровом опыте отдельно записывайте версию модели и её ограничения: одинаковый код может воспроизводить собственное упрощение.'
],'«Смешал жидкости, получилось» почти непроверяемо. «Указал составы, фактический перенос, наблюдаемое событие и остаток» уже даёт основу для сравнения.',
 'Повторяемость результата и истинность объяснения проверяются разными вопросами.','Составьте протокол, по которому можно сравнить два виртуальных опыта.',[
 q('Одинаковый результат одной программы гарантирует правильную модель природы?',['Нет','Да'],0,['Детерминированная ошибка тоже может воспроизводиться.','Внешняя проверка модели остаётся необходимой.']),
 q('Какая запись полезнее для повторения?',['Составы, порядок, фактические количества и наблюдения','Только впечатление «было красиво»'],0,['Это позволяет восстановить условия и критерии.','Эмоциональная оценка не заменяет протокол.'])
],lab('Запишите сравнимый протокол',{kind:'pour',receiver:{kind:'flask',substance:'potassium_hydroxide',volume:15},donor:{substance:'hcl',volume:15}},{type:'reaction',id:'potassium_neutralization'},['Проведите виртуальную реакцию KOH с HCl.','Запишите фактически выполненные действия и сравните продукт с прежним опытом NaOH + HCl.'],'Событие подтверждено. Для воспроизводимости важна ваша запись условий, а не только отметка прохождения.'));

lesson(59,12,'Гипотеза должна рисковать оказаться неверной','Как отличить исследование от поиска подтверждения?',[
 'Сильная гипотеза делает конкретный прогноз, который может не выполниться. Полезно заранее назвать альтернативное объяснение и данные, которые позволят их различить. Отсутствие наблюдаемого эффекта требует учитывать чувствительность метода.',
 'Модель оценивают не только по согласованию с известными примерами, но и по новым проверкам. Нужно отделять параметр, подогнанный под данные, от независимого предсказания. В отчёте неудачный прогноз может быть самым ценным результатом.'
],'Если ожидаемый осадок не появился, возможны малое количество, другой pH, недостаточное время или отсутствие правила в игре. Один отрицательный результат не выбирает причину автоматически.','Заранее определите, что опровергнет ваш прогноз и какие альтернативы останутся.','Запишите гипотезу, опровергающее наблюдение и две альтернативные причины результата.',[
 q('Гипотеза, объясняющая любой возможный итог без изменений, хорошо проверяется?',['Нет','Да'],0,['Она не рискует столкнуться с опровергающим результатом.','Проверка требует различимых прогнозов.']),
 q('Ненаблюдаемый сигнал означает строго нулевое количество вещества?',['Не обязательно, есть предел обнаружения','Всегда'],0,['Метод может быть недостаточно чувствителен.','Отсутствие сигнала и отсутствие вещества — разные утверждения.'])
],analysis('Проверьте формулировку','Выберите более проверяемую гипотезу.',['При заданных составах добавление OH⁻ даст обнаружимый осадок Cu(OH)₂','При любом исходе химия как-нибудь объяснит результат'],0,'Первая формулировка задаёт условия и наблюдаемый прогноз, который может не выполниться.'));

lesson(60,12,'Первый исследовательский отчёт','Соедините вопрос, модель, действие и честный вывод.',[
 'Заключительный проект — маленькое исследование знакомого осаждения. Сначала сформулируйте прогноз о составе и наблюдении, затем проведите виртуальный опыт. В отчёте разделите исходные данные, расчёт, результат, альтернативы и ограничения.',
 'Этот маршрут даёт основы языка и логики химии, а не профессиональную квалификацию. Дальнейшая работа требует систематических курсов, математики, освоения реальных методов, безопасной лабораторной подготовки под руководством и независимых проектов. Хороший финал курса — следующий проверяемый вопрос.'
],'В отчёте о CuSO₄ и NaOH укажите не только голубой осадок, но и сопутствующую соль, возможный избыток, границы измерения и то, что модель не различает все реальные фазы.','Полноценный вывод показывает и то, что установлено, и то, что осталось неизвестным.','Создайте итоговую запись: вопрос; гипотеза; расчёт; метод; наблюдения; вывод; ограничения; следующий опыт.',[
 q('Достаточно ли красивой анимации для исследовательского вывода?',['Нет, нужен состав, метод и проверяемая аргументация','Да'],0,['Визуальный эффект лишь один вид наблюдения.','Анимация не заменяет анализ и ограничения.']),
 q('Что означает завершение этого маршрута?',['Освоен вводный путь и обозначены следующие ступени обучения','Получена полная профессиональная квалификация химика'],0,['Курс служит основой для дальнейшей учёбы и практики.','Короткая симуляция не заменяет профессиональную подготовку.'])
],lab('Проведите итоговый опыт и оформите вывод',{kind:'pour',receiver:{kind:'flask',substance:'cuso4',volume:20},donor:{substance:'naoh',volume:20}},{type:'reaction',id:'copper_precipitate'},['До переливания запишите прогноз и ограничивающий реагент для выбранных количеств.','Проведите опыт, затем сравните прогноз с составом и журналом.','Оформите итоговую заметку, включая оставшиеся вопросы и границы модели.'],'Реакция зарегистрирована. Завершение проекта — ваш обоснованный отчёт, а не обещание профессиональной квалификации.'));
